-int DNSClient::inet_aton(const char* address, IPAddress& result)
-{
-    uint16_t acc = 0; // Accumulator
-    uint8_t dots = 0;
-
-    while (*address)
-    {
-        char c = *address++;
-        if (c >= '0' && c <= '9')
-        {
-            acc = acc * 10 + (c - '0');
-            if (acc > 255) {
-                // Value out of [0..255] range
-                return 0;
-            }
-        }
-        else if (c == '.')
-        {
-            if (dots == 3) {
-                // Too much dots (there must be 3 dots)
-                return 0;
-            }
-            result[dots++] = acc;
-            acc = 0;
-        }
-        else
-        {
-            // Invalid char
-            return 0;
-        }
-    }
-
-    if (dots != 3) {
-        // Too few dots (there must be 3 dots)
-        return 0;
-    }
-    result[3] = acc;
-    return 1;
-}
