-		theGSM3ShieldV1ModemCore.genericCommand_rq(_command_AT);
-	}
-	else if(ct==2)
-	{
-		// Wait for AT - OK.
-	   if(theGSM3ShieldV1ModemCore.genericParse_rsp(resp))
