-			  if((uint8_t)__XOFF__ & i)
-				tx_pin_write(HIGH);
-			  else
-				tx_pin_write(LOW);
-			}
-		}
-
-		if(fullbuffer&&(!capturado_fullbuffer))
-		{
-			tunedDelay(_rx_delay_intrabit);
-			tx_pin_write(HIGH);	
-		}
-		
-		// So, we know the buffer is full, and we have sent a XOFF
