-  if (oldPaddleX != paddleX || oldPaddleY != paddleY) {
-    TFTscreen.rect(oldPaddleX, oldPaddleY, 20, 5);
-  }
-
-  // draw the paddle on screen, save the current position
-  // as the previous.
-  TFTscreen.fill(255, 255, 255);
-
-  TFTscreen.rect(paddleX, paddleY, 20, 5);
-  oldPaddleX = paddleX;
