-  unsigned int timeout = SPI_TIMEOUT;
-
-  if (pcs > 14 || lastxfer > 1) {
-    return SPI_ERROR_ARGUMENT;
-  }
-
-  while (!(spi->sr & AVR32_SPI_SR_TDRE_MASK)) {
-    if (!timeout--) {
-      return SPI_ERROR_TIMEOUT;
-    }
-  }
-
-  spi->tdr = (data << AVR32_SPI_TDR_TD_OFFSET) |
