-
-  if (ret == (SPI_ERROR_OVERRUN + SPI_ERROR_MODE_FAULT)) {
-    return SPI_ERROR_OVERRUN_AND_MODE_FAULT;
-  }
-  else if (ret > 0) {
-    return ret;
-  } else {
-    return SPI_OK;
-  }
-}

