-static struct pbuf *
-low_level_input(struct netif *netif)
-{
-        struct pbuf *p;
-	struct wlif_t *priv = (struct wlif_t*) netif->state;
-
-        char *stripped_pkt;
-        size_t stripped_pkt_len;
-        u16_t vlan;
-        u8_t rx_hdr_size;
-        int status;
-        u16_t len;
