-int console_add_cmd(const char* str, cmd_cb_t cb, void* ctx)
-{
-        uint32_t i;
-        for (i = 0; i < ARRAY_SIZE(cmd_list); i++)
-                if (!cmd_list[i].cb)
-                        break;
-        
-        if (i == ARRAY_SIZE(cmd_list))
-                return -1;
-        
-        cmd_list[i].str = str;
-        cmd_list[i].cb = cb;
