-
-void SpiDrv::sendBuffer(uint8_t* param, uint16_t param_len, uint8_t lastParam)
-{
-    uint16_t i = 0;
-
-    // Send Spi paramLen
-    sendParamLen16(param_len);
-
-    // Send Spi param data
-    for (i=0; i<param_len; ++i)
-    {
-        spiTransfer(param[i]);
-    }
-
-    // if lastParam==1 Send Spi END CMD
-    if (lastParam == 1)
-        spiTransfer(END_CMD);
-}
