-
-void SpiDrv::sendParam(uint16_t param, uint8_t lastParam)
-{
-    // Send Spi paramLen
-    sendParamLen8(2);
-
-    spiTransfer((uint8_t)((param & 0xff00)>>8));
-    spiTransfer((uint8_t)(param & 0xff));
-
-    // if lastParam==1 Send Spi END CMD
-    if (lastParam == 1)
-        spiTransfer(END_CMD);
-}
